priv struct CreateRecording {
  mut attempt : Int32
  mut phase : String
}

///|
let create_recording : CreateRecording = {
  attempt: 0,
  phase: "input-validation",
}

///|
priv enum CreateEvidence {
  Inputs
  IdentitySelection(String, String)
  Storage(String, String)
  VolumeCleanup(String, Json)
  Configuration(String, String, String?)
  Request(String, Bool)
  Lookup(String)
  Selection(String, String, String?, String, String)
  Clone(String?, String, Array[String], String?)
  TaskHeadRetry(String)
  AcquiredCommit(String)
  Checkout(String, String, Bool)
}

///|
priv enum DiagnosticValueKind {
  Identity
  Workspace
  RefName
  Commit
}

///|
fn diagnostic_value(value : String?, kind : DiagnosticValueKind) -> Json {
  match value {
    None => { "state": "unset" }
    Some("") => { "state": "empty" }
    Some(text) => {
      let valid = match kind {
        Commit => valid_commit(text)
        Workspace => valid_workspace_id(text)
        Identity => text.length() <= 128 && valid_context(text)
        RefName => diagnostic_ref(text)
      }
      let credential_form = text
        .split("/")
        .iter()
        .any(part => {
          [
            "ghp_", "gho_", "ghu_", "ghs_", "ghr_", "github_pat_", "glpat-", "sk-",
            "eyJ",
          ]
          .iter()
          .any(prefix => part.has_prefix(prefix))
        })
      if valid && !credential_form {
        { "state": "valid", "value": text }
      } else {
        { "state": "invalid" }
      }
    }
  }
}

///|
// A recording grammar, never a replacement for checkout validation. Excludes
// URLs, credential forms, control characters and Git's invalid ref syntax.
fn diagnostic_ref(text : String) -> Bool {
  text.length() <= 1024 &&
  !text.has_prefix("-") &&
  !text.contains("..") &&
  text
  .split("/")
  .iter()
  .all(part => {
    part != "" &&
    !part.has_prefix(".") &&
    !part.has_suffix(".") &&
    !part.has_suffix(".lock")
  }) &&
  text
  .iter()
  .all(c => {
    (c >= 'a' && c <= 'z') ||
    (c >= 'A' && c <= 'Z') ||
    (c >= '0' && c <= '9') ||
    c == '/' ||
    c == '-' ||
    c == '_' ||
    c == '.'
  })
}

///|
fn CreateEvidence::to_json(self : CreateEvidence) -> Json {
  match self {
    VolumeCleanup(volume, plan) => { "volume": volume, "cleanup": plan }
    IdentitySelection(slug, id) =>
      { "repositorySlug": redact_credentials(slug), "workspaceId": id }
    Storage(volume, root) =>
      {
        "projectRoot": if root == "" {
          Json::null()
        } else {
          Json::string(redact_credentials(root))
        },
        "volume": volume,
        "mountPath": "/workspaces/.orca",
        "profilePath": "/workspaces/.orca/.profile",
        "worktreeBasePath": "/workspaces/.orca",
      }
    Inputs => {
      let inputs = Json::empty_object()
      for
        (name, kind) in [
          ("ORCA_VM_INSTANCE_ID", Workspace),
          ("ORCA_RECIPE_ID", Identity),
          ("ORCA_REPO_REF", RefName),
          ("ORCA_REPO_REF_HEAD", Commit),
          ("ORCA_REPO_BRANCH", RefName),
        ] {
        set_field(inputs, name, diagnostic_value(@env.get_env_var(name), kind))
      }
      inputs
    }
    Configuration(mode, connection, build_ref) =>
      {
        "checkoutMode": if mode == "orca-worktree" || mode == "provisioned-root" {
          Json::string(mode)
        } else {
          Json::string("invalid")
        },
        "connection": connection,
        "configuredBuildRef": diagnostic_value(build_ref, RefName),
      }
    Request(build_ref, task_build) =>
      {
        "buildRef": diagnostic_value(Some(build_ref), RefName),
        "selectionReason": if task_build {
          "orca-input"
        } else {
          "configured-build-ref"
        },
      }
    Lookup(lookup_ref) =>
      { "lookupRef": diagnostic_value(Some(lookup_ref), RefName) }
    Selection(build_ref, lookup_ref, branch, commit, reason) =>
      {
        "buildRef": diagnostic_value(Some(build_ref), RefName),
        "lookupRef": diagnostic_value(Some(lookup_ref), RefName),
        "resolvedBranch": diagnostic_value(branch, RefName),
        "resolvedCommit": diagnostic_value(Some(commit), Commit),
        "selectionReason": reason,
      }
    Clone(branch, commit, args, reason) => {
      let (strategy, origin) = diagnostic_clone_strategy(args)
      {
        "sourceKind": if branch is Some(_) {
          "branch"
        } else {
          "commit"
        },
        "branch": diagnostic_value(branch, RefName),
        "commit": diagnostic_value(Some(commit), Commit),
        "cloneStrategy": strategy,
        "strategySource": origin,
        "fallback": reason is Some(_),
        "fallbackReason": match reason {
          Some(value) => Json::string(value)
          None => Json::null()
        },
      }
    }
    TaskHeadRetry(commit) =>
      {
        "commit": diagnostic_value(Some(commit), Commit),
        "fallback": true,
        "fallbackReason": "task-head-mismatch",
      }
    AcquiredCommit(actual) =>
      {
        "scope": "build-checkout",
        "actualCommit": diagnostic_value(Some(actual), Commit),
      }
    Checkout(actual, expected, matches) =>
      {
        "scope": "build-checkout",
        "actualCommit": diagnostic_value(Some(actual), Commit),
        "expectedCommit": diagnostic_value(Some(expected), Commit),
        "matches": matches,
      }
  }
}

///|
// Inspect only the strategy flags in the actual invocation. Other arguments
// never enter the diagnostic record. Devsy uses the last valid repeated flag.
fn diagnostic_clone_strategy(args : Array[String]) -> (String, String) {
  let mut strategy = "full"
  let mut count = 0
  let mut invalid = false
  let mut index = 0
  while index < args.length() {
    let argument = args[index]
    let value = if argument == "--git-clone-strategy" {
      count += 1
      index += 1
      if index < args.length() {
        Some(args[index])
      } else {
        None
      }
    } else if argument.has_prefix("--git-clone-strategy=") {
      count += 1
      Some(argument[21:].to_owned())
    } else {
      None
    }
    if count > 0 &&
      (
        argument == "--git-clone-strategy" ||
        argument.has_prefix("--git-clone-strategy=")
      ) {
      match value {
        Some("") => strategy = "full"
        Some("shallow" | "blobless" | "treeless" | "bare" as known) =>
          strategy = known
        _ => invalid = true
      }
    }
    index += 1
  }
  (
    if invalid {
      "invalid"
    } else {
      strategy
    },
    if count > 1 {
      "upArgs"
    } else {
      "adapter"
    },
  )
}
///|
async fn server_connection(
  state : Json,
  install : Bool,
  deadline? : UInt64,
) -> Json {
  if install {
    let script = server_install_script()
    ignore(remote(state, script, "orca-install"))
    prepare_orca_storage(state)
    initialize_orca_settings(state)
  }
  let output = recover_server(state, connection_result=true)
  ensure_ssh_worker(state, Some(reserve_server_port(state)), deadline?)
  output
}

///|
async fn recover_server(
  state : Json,
  connection_result~ : Bool = false,
) -> Json {
  let directory = required(state, "tunnelDirectory")
  let lock = @fs.open(
    directory + "/server.lock",
    mode=ReadWrite,
    create_mode=OpenOrCreate,
    permission=0o600,
  )
  defer lock.close()
  @async.with_timeout(30000, async fn() {
    while !lock.try_lock(Exclusive) {
      @async.sleep(100)
    }
  })
  guard @fs.exists(directory + "/enabled") && !@fs.exists(directory + "/paused") else {
    raise AdapterError("Connection recovery cancelled")
  }
  let output = if !connection_result && server_is_running(state) {
    save_diagnostic(
      "recover-server",
      "reuse",
      tunnel_directory=directory,
      recording=workspace_recording(state),
    )
    Json::null()
  } else {
    save_diagnostic(
      "recover-server",
      "start",
      tunnel_directory=directory,
      recording=workspace_recording(state),
    )
    if field(state, "orcaVolume") is Some(_) {
      prepare_orca_storage(state)
      let installation = remote(
          state, "if test -x \"$HOME/.local/share/orca-env-devsy/orca/current/orca-ide\"; then printf installed; else printf missing; fi",
          "orca-install-probe",
        )
        .trim()
        .to_owned()
      match installation {
        "installed" => ()
        "missing" =>
          ignore(remote(state, server_install_script(), "orca-install"))
        _ => raise AdapterError("Invalid Orca installation probe result")
      }
    }
    let output = launch_server(state)
    configure_orca_project(state)
    output
  }
  @fs.write_file(directory + "/server-enabled", "", permission=0o600)
  output
}

///|
async fn launch_server(state : Json) -> Json {
  let root = required(state, "projectRoot")
  let port = reserve_server_port(state)
  let script = (if field(state, "orcaVolume") is Some(_) {
      "export ORCA_USER_DATA_PATH=/workspaces/.orca/.profile; "
    } else {
      ""
    }) +
    server_launch_script(root, port)
  let result = @json.parse(remote(state, script, "orca-serve"))
  let connection = match field(result, "connection") {
    Some(value) => value
    None => result
  }
  guard required(connection, "pairingCode") != "" else {
    raise AdapterError("Orca returned no pairing code")
  }
  @fs.write_file(
    required(state, "tunnelDirectory") + "/pairing-code",
    required(connection, "pairingCode"),
    permission=0o600,
  )
  let output : Json = {
    "type": "orca-server",
    "pairingCode": required(connection, "pairingCode"),
    "projectRoot": root,
  }
  output
}

///|
fn server_launch_script(root : String, port : Int32) -> String {
  // The Linux wrapper in 1.4.224 resolves the app root inside app.asar.unpacked.
  // Invoke the package-declared CLI entry so Orca prepares its bundled orcad.
  "ELECTRON_RUN_AS_NODE=1 exec \"$HOME/.local/share/orca-env-devsy/orca/current/orca-ide\" \"$HOME/.local/share/orca-env-devsy/orca/current/resources/app.asar/out/cli/index.js\" serve --recipe-json --project-root " +
  quote(root) +
  " --port 47121 --pairing-address " +
  quote("ws://127.0.0.1:\{port}") +
  // A detached server must not retain the SSH channel's stderr pipe.
  " 2>/dev/null"
}

