///|
suberror AdapterError {
  AdapterError(String)
} derive(@debug.Debug)

///|
fn required(value : Json, name : String) -> String raise {
  match field(value, name) {
    Some(Json::String(text)) if text != "" => text
    _ => raise AdapterError("Missing or invalid \{name}")
  }
}

///|
fn environment(name : String) -> String raise {
  match @env.get_env_var(name) {
    Some(value) if value != "" => value
    _ => raise AdapterError("Missing \{name}")
  }
}

///|
fn quote(text : String) -> String {
  let escaped_quote =
    #|'"'"'
  "'" + text.replace_all(old="'", new=escaped_quote) + "'"
}

///|
async fn command_result(
  program : String,
  args : Array[String],
  stage : String,
  environment? : Map[String, String],
  cwd? : StringView,
) -> (Int32, String, String) {
  let recording = environment
    .unwrap_or(@env.get_env_vars())
    .get("ORCA_ENV_DEVSY_RECORDING") !=
    Some("0")
  save_diagnostic(stage, "started", recording~)
  let started = @env.now()
  let progress = Progress::new(stage, environment?)
  progress_message(stage + ": running…")
  let mut failure_kind = "process_api"
  let mut failure_errno = None
  let mut failure_phase = None
  let (status, output, errors) = {
    errdefer {
      save_diagnostic(
        stage,
        if @async.is_being_cancelled() {
          "cancelled"
        } else {
          "process-error"
        },
        error_type=failure_kind,
        os_errno?=failure_errno,
        phase?=failure_phase,
        error_message=progress.failure_detail(),
        details_truncated=progress.details_truncated,
        recording~,
      )
      progress_message(stage + ": failed (" + progress_timing(started) + ")")
    }
    try {
      let (out, stdout) = @process.read_from_process()
      defer out.close()
      let (err, stderr) = @process.read_from_process()
      defer err.close()
      @async.with_task_group(async fn(group) {
        let child = @process.spawn(
          group,
          program,
          args,
          extra_env?=environment,
          inherit_env=environment is None,
          cwd?,
          stdout~,
          stderr~,
        )
        let output = group.spawn(async fn() {
          progress.read_output(
            out,
            capture=true,
            statuses=devsy_progress_stage(stage),
            messages=stage == "orca-install" || stage == "checkout-workspace",
          )
        })
        let errors = group.spawn(async fn() {
          progress.read_output(
            err,
            capture=false,
            messages=devsy_progress_stage(stage) ||
              stage == "orca-install" ||
              stage == "checkout-workspace",
          )
        })
        (child.wait(), output.wait(), errors.wait())
      })

3:description: 開発、修正、リファクタリング、レビュー対応など、リポジトリを変更するタスクで、対象リポジトリに応じた観測可能な実装、検証、ドキュメントおよび再現性の方針を適用する。
10:- 変更は明示されたrepository内に限定する。依頼、適用guidance、sourceおよび実環境から目的、observableな成功条件、hard constraint、明示された手段、non-goalおよび未検証の前提をclosed setとして保持する。
53:独立code reviewは従来どおり、次のclosed setに該当するときだけ必須とする。Doc reviewの必須条件とは別に判定する。
60:Closed-set triggerに該当しない既存contract内の局所修正、doc、単純な設定および決定的生成物は独立code review不要である。
62:独立doc reviewは、共通guidanceのdocに当たる新設・更新・削除すべてで必須とする。Docだけ、code commentだけ、PR説明だけの変更も対象であり、拡張子やcode reviewの要否で免除しない。PR説明などrepo外の文面も変更前後をsnapshotに含め、公開・更新前にreviewする。
68:- Commit前に元の依頼とclosed setを読み直し、各項目を証拠、明示的な対象外または残作業へ対応付ける。Git stateとdiffを再確認し、release対象では開始時の提案が送信済みであることと、task全体の承認済みrelease要否・上限と予定するcommit群の影響を照合する。提案の送信漏れが判明したら直ちに送り、commitなしでできる残作業を進める。未承認、SemVerで基準releaseを確認できず影響が確定しない場合、または範囲外ならcommitを保留して残作業と必要な判断を示す。Commitできる場合は自分の変更だけを明示的にstageして論理単位でcommitする。未確定のまま残す明示指示がなければ、完了した変更はlocal commitへ確定する。
