    96	  let (stdin, writer) = @process.write_to_process()
    97	  defer writer.close()
    98	  @async.with_task_group(async fn(group) {
    99	    let output = group.spawn(async fn() {
   100	      @process.collect_output(
   101	        program[:],
   102	        args[:],
   103	        extra_env=environment,
   104	        inherit_env=false,
   105	        stdin~,
   106	      )
   107	    })
   108	    if input is Some(value) {
   109	      writer.write(value)
   110	    }
   111	    writer.close()
   112	    let (status, stdout, stderr) = output.wait()
   113	    guard status == 0 else {
   114	      let detail = try {
   115	        let error = @json.parse(stderr.text())
   116	        let phase = required(error, "phase")
   117	        let code = required(error, "code")
   118	        if ["load", "read", "normalize", "input", "profile", "write", "verify"].contains(
   119	            phase,
   120	          ) &&
   121	          ["EACCES", "ENOENT", "EBUSY", "ENOSPC", "INCOMPATIBLE", "INVALID"].contains(
   122	            code,
   123	          ) {
   124	          phase + ": " + code
   125	        } else {
   126	          "subprocess failed"
   127	        }
   128	      } catch {
   129	        _ => "subprocess failed"
   130	      }
   131	      raise AdapterError(
   132	        "Orca settings transfer failed (exit \{status}, " + detail + ")",
   133	      )
   134	    }
   135	    guard stdout.binary().length() <= 4194304 else {
   136	      raise AdapterError("Orca settings result exceeds size limit")
   137	    }
   138	    stdout.text()
   139	  })
   140	}
